    let mut colors_child_texts = Vec::<Option<String>>::new();
    let mut colors_nested_child_names = Vec::<Vec<String>>::new();
    let mut colors_nested_child_attr_maps = Vec::<Vec<BTreeMap<String, String>>>::new();
    let mut colors_nested_child_texts = Vec::<Vec<Option<String>>>::new();
    let mut colors_grandchild_names = Vec::<Vec<Vec<String>>>::new();
    let mut colors_grandchild_attr_maps = Vec::<Vec<Vec<BTreeMap<String, String>>>>::new();
    let mut colors_grandchild_texts = Vec::<Vec<Vec<Option<String>>>>::new();
    let mut colors_great_grandchild_names = Vec::<Vec<Vec<Vec<String>>>>::new();
    let mut colors_great_grandchild_attr_maps =
        Vec::<Vec<Vec<Vec<BTreeMap<String, String>>>>>::new();
    let mut colors_great_grandchild_texts = Vec::<Vec<Vec<Vec<Option<String>>>>>::new();
    let mut colors_great_great_grandchild_names = Vec::<Vec<Vec<Vec<Vec<String>>>>>::new();
    let mut colors_great_great_grandchild_attr_maps =
        Vec::<Vec<Vec<Vec<Vec<BTreeMap<String, String>>>>>>::new();
    let mut colors_great_great_grandchild_texts = Vec::<Vec<Vec<Vec<Vec<Option<String>>>>>>::new();
    let mut num_fmts_declared_count = None::<usize>;
    let mut fonts_declared_count = None::<usize>;
